// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(ts > block.timestamp);
        vm.assume(actor != address(c));
        vm.deal(actor, 20 ether);

        // first call: succeeds, must record this timestamp
        vm.roll(ts);
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        assertTrue(c.pastBlockTime() == ts, "timestamp not recorded");

        // second call at the SAME timestamp: must revert since pastBlockTime == ts
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether, gas: 100000}() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "second same-timestamp call must revert");
    }
}

