contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockDelta, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        uint256 target = bound(blockDelta, 1, 100000);
        vm.roll(target);
        vm.warp(target + 1); // ensure block.timestamp > pastBlockTime initially
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);
        if (block.number % 15 == 0) {
            assert(address(c).balance == 0);
        } else {
            assert(address(c).balance == 10 ether);
        }
    }
}

