// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 t2, uint256 amount, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        t1 = bound(t1, 1, 1e12);            // timestamp of the successful call (must exceed initial 0)
        t2 = bound(t2, t1 + 1, t1 + 1e12);  // later timestamp for the failing call
        vm.assume(amount != 10 ether);      // wrong value => call must revert

        // successful call: correct value, timestamp t1 > pastBlockTime(0)
        vm.warp(t1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        assertTrue(c.pastBlockTime() == t1);

        // failing call at t2: wrong msg.value, must NOT change pastBlockTime
        vm.warp(t2);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: amount}("");
        assertTrue(!ok2);

        // RULE: pastBlockTime still records the last successful timestamp t1.
        // Reference holds for all inputs; mutant resets it to 0 before the require.
        assertTrue(c.pastBlockTime() == t1);
    }
}
